export const GLOSSARY_SHARD = Object.freeze({"cryptocurrency":{"slug":"cryptocurrency","cat":"basics","en":"Cryptocurrency","contentLocale":"tr","term":"Kripto para (cryptocurrency)","aka":["kripto para birimi","kripto varlık","cryptocurrency","kripto"],"short":"Kripto para, bir merkez bankası ya da şirket yerine bir blockchain ağı tarafından kaydı tutulan, kriptografiyle korunan ve internet üzerinden doğrudan kişiden kişiye gönderilebilen dijital bir varlıktır.","body":[["Banka hesabınızdaki lira bankanın veritabanında bir satırdır. Kripto parada ise bakiyeniz herkese açık bir ",["blockchain","blockchain"],"'de bir adrese bağlı olarak kayıtlıdır. O adresi yönetme yetkisi, yalnızca sizin bilmeniz gereken özel anahtardadır. ",["Özel anahtar","private-key"]," kimdeyse coinler fiilen onundur."],["Kripto paraları kabaca birkaç gruba ayırabilirsiniz: değer saklama aracı olarak görülen ",["Bitcoin","bitcoin"],", ",["akıllı kontrat","smart-contract"]," platformlarının yerel coinleri (",["ETH","ethereum"],", SOL gibi), fiyatı dolara sabitlenmeye çalışılan ",["stablecoin","stablecoin"],"'ler (USDT, USDC) ve proje token'ları. Hepsinin riski, likiditesi ve kullanım amacı farklıdır."],"Fiyatlar yalnızca arz ve talep ile belirlenir; arkasında devlet güvencesi yoktur. Bu yüzden oynaklık yüksektir. Türkiye'de kripto varlık hizmet sağlayıcıları 2024'te çıkan yasayla SPK lisansına bağlandı; vergi ve düzenleme kuralları ülkeden ülkeye değişir."],"example":"Bir borsada 1.000 USDT ile 0,4 ETH aldığınızı düşünün; bu, ETH'nin 2.500 USDT olduğu anlamına gelir. ETH'yi borsada bıraktığınızda bakiye borsanın kayıtlarında görünür ve özel anahtarları borsa tutar. Aynı 0,4 ETH'yi kendi cüzdanınıza çekerseniz kayıt doğrudan Ethereum blockchain'inde sizin adresinize geçer. Fiyat yüzde 20 düşüp 2.000 USDT olursa varlığınızın değeri 800 USDT'ye iner; nerede sakladığınız bu oynaklığı değiştirmez, yalnızca kimin kontrol ettiğini değiştirir.","mistakes":["Bütün kripto paraların Bitcoin gibi sınırlı arza sahip olduğunu varsaymak.","Özel anahtarı veya kurtarma ifadesini bir ekran görüntüsü olarak telefonda saklamak.","Stablecoin'lerin hiçbir risk taşımadığını düşünmek; ihraççı ve rezerv yapısı da önemlidir."],"faq":[{"q":"Kripto para gerçek para mı?","a":"Kripto paralar dijital varlıklardır ve çoğu ülkede yasal ödeme aracı sayılmaz. Yine de borsalarda liraya veya dolara çevrilebilir ve bazı yerlerde ödeme için kabul edilir."},{"q":"Kripto para nasıl alınır?","a":"En yaygın yol, kimlik doğrulaması (KYC) yaptığınız lisanslı bir borsada hesap açıp para yatırmak ve spot piyasada alım yapmaktır. Aldıktan sonra isterseniz kendi cüzdanınıza çekebilirsiniz."},{"q":"Kaç tane kripto para var?","a":"On binlerce token ve coin vardır ve sayı sürekli değişir. Bunların küçük bir kısmının anlamlı bir işlem hacmi ve likiditesi bulunur."}],"title":"Kripto para nedir? Nasıl çalışır?","description":"Kripto paranın ne olduğunu, blockchain'de nasıl kaydedildiğini ve özel anahtarın neden bu kadar önemli olduğunu öğrenin.","related":[["blockchain","Blockchain (blok zinciri)","Blockchain (blok zinciri), işlemlerin bloklar halinde gruplanıp birbirine kriptografik olarak bağlandığı, binlerce bilgisayar tarafından ortaklaşa tutulan ve geçmişi sonradan değiştirilemeyen dijital bir kayıt defteridir."],["bitcoin","Bitcoin (BTC)","Bitcoin (BTC), 2009'da Satoshi Nakamoto takma adıyla başlatılan, iş ispatı ile çalışan ve toplam arzı 21 milyon BTC ile sınırlı olan ilk ve piyasa değeri en büyük kripto paradır."],["altcoin","Altcoin","Altcoin, Bitcoin dışındaki tüm kripto paralar için kullanılan genel bir terimdir; Ethereum ve Solana gibi büyük ağlardan küçük proje token'larına ve memecoin'lere kadar geniş bir yelpazeyi kapsar."],["stablecoin","Stablecoin (sabit coin)","Stablecoin, değerini genellikle ABD doları gibi bir referans varlığa sabitlemeyi amaçlayan ve kripto piyasasında nakit gibi kullanılan bir kripto paradır."],["centralized-exchange","Merkezi borsa (CEX)","Merkezi borsa (CEX), bir şirket tarafından işletilen, kullanıcıların fonlarını saklayan ve alıcılarla satıcıları kendi emir defterinde eşleştiren kripto para alım satım platformudur."]],"lesson":{"id":"E01","slug":"can-i-buy-part-of-a-bitcoin","ep":1,"title":"Bir bitcoin o kadar pahalıyken yine de biraz alabilir miyim?"},"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"smart-contract":{"slug":"smart-contract","cat":"basics","en":"Smart contract","contentLocale":"tr","term":"Akıllı kontrat (smart contract)","aka":["akıllı sözleşme","smart contract"],"short":"Akıllı kontrat (smart contract), bir blockchain üzerinde çalışan ve önceden yazılmış koşullar gerçekleştiğinde kimsenin onayına gerek kalmadan otomatik olarak işlem yapan bir programdır.","body":[["Akıllı kontratı bir otomat makinesine benzetebilirsiniz: doğru miktarı yatırırsanız ürün otomatik olarak düşer, araya kimse girmez. ",["Blockchain","blockchain"],"'deki kontrat da örneğin belirli bir token yatırıldığında karşılığında başka bir token gönderebilir."],[["Ethereum","ethereum"]," bu fikri yaygınlaştırdı; bugün BNB Chain, Solana, Avalanche ve birçok layer 2 de akıllı kontrat çalıştırır. Merkeziyetsiz borsalar, borç verme protokolleri, ",["stablecoin","stablecoin"],"'ler ve ",["NFT","nft"],"'ler bu kontratlar üzerine kuruludur. Bir kontratla etkileşime girmek ",["gas ücreti","gas-fee"]," gerektirir."],["Kontrat kodu yayımlandıktan sonra çoğu zaman değiştirilemez; bir hata varsa saldırganlar bunu kullanabilir. Bazı kontratlar ise yönetici anahtarıyla güncellenebilir, bu da başka bir risk demektir. Denetim (audit) raporu bir güvence sağlar ama hatasızlık garantisi değildir. Bir kontrata token ",["harcama izni","token-approval"]," (approval) verirken de dikkatli olmanız gerekir."]],"example":"Bir DEX'te 3.000 USDC karşılığında ETH almak istediğinizi varsayalım. Cüzdanınız önce kontratın sizin adınıza 3.000 USDC harcamasına izin vermenizi (approval) ister, ardından takas işlemini gönderirsiniz. Kontrat, havuzdaki oranı kullanarak yüzde 0,3 havuz ücretini (9 USDC) likidite sağlayıcılara ayırır ve kalan 2.991 USDC karşılığında, ETH 3.000 USDC iken yaklaşık 0,997 ETH gönderir. Bu iki işlem için ayrıca gas ödersiniz. Tüm adımlar kontrat kodu tarafından otomatik yapılır; ne bir çalışan ne de bir aracı müdahale eder.","mistakes":["Tanımadığınız bir sitedeki kontrata sınırsız token harcama izni vermek.","Denetim raporu olan her kontratın tamamen güvenli olduğunu düşünmek.","Kontratla etkileşimde başarısız olan işlemlerin de gas ücreti tükettiğini bilmemek."],"faq":[{"q":"Akıllı kontrat hukuki bir sözleşme mi?","a":"Genellikle hayır. Akıllı kontrat bir yazılımdır; adındaki sözleşme kelimesi otomatik uygulanan kuralları ifade eder. Hukuki statüsü ülkeden ülkeye değişir."},{"q":"Akıllı kontratlar değiştirilebilir mi?","a":"Bazıları değiştirilemez, bazıları ise yükseltilebilir (upgradeable) şekilde tasarlanır. Yükseltilebilir kontratlarda kimin değişiklik yapabildiğini bilmek önemlidir."}],"title":"Akıllı kontrat (smart contract) nedir?","description":"Akıllı kontratın ne olduğunu, DEX ve DeFi'de nasıl çalıştığını ve token onayı ile kod hatalarının risklerini öğrenin.","related":[["ethereum","Ethereum (ETH)","Ethereum, akıllı kontratların çalıştırılabildiği programlanabilir bir blockchain'dir; yerel coini Ether (ETH) hem işlem ücretlerini (gas) ödemek hem de ağı hisse ispatıyla güvence altına almak için kullanılır."],["defi","DeFi (merkeziyetsiz finans)","DeFi (merkeziyetsiz finans), borç verme, takas, getiri elde etme gibi finansal hizmetlerin banka veya borsa yerine blokzincirdeki akıllı sözleşmelerle sunulduğu açık uygulamalar ekosistemidir."],["token-approval","Token onayı (token approval / allowance)","Token onayı, cüzdanınızdaki belirli bir token'ı sizin adınıza harcayabilmesi için bir akıllı sözleşmeye verdiğiniz izindir ve sınırsız verilen onaylar istismar edilirse cüzdanınızı boşaltabilir."],["oracle","Blokzincir oracle'ı (kâhin)","Blokzincir oracle'ı, fiyatlar veya hava durumu gibi blokzincir dışındaki verileri akıllı sözleşmelere güvenilir biçimde taşıyan hizmettir; DeFi protokolleri teminat ve tasfiye hesaplarında bu verilere dayanır."],["gas-fee","Gas ücreti (gas fee)","Gas ücreti, bir blockchain'de işlem göndermek veya akıllı kontrat çalıştırmak için ağa ödenen ücrettir; Ethereum'da harcanan gas miktarı ile gas fiyatının çarpımı olarak ETH cinsinden hesaplanır."]],"lesson":null,"coin":{"slug":"ethereum","name":"Ethereum","symbol":"ETH"},"tool":null,"cta":false},"gas-fee":{"slug":"gas-fee","cat":"basics","en":"Gas fee","contentLocale":"tr","term":"Gas ücreti (gas fee)","aka":["gas","gas fee","ağ ücreti","işlem ücreti"],"short":"Gas ücreti, bir blockchain'de işlem göndermek veya akıllı kontrat çalıştırmak için ağa ödenen ücrettir; Ethereum'da harcanan gas miktarı ile gas fiyatının çarpımı olarak ETH cinsinden hesaplanır.","body":[["Gas, bir işlemin ne kadar hesaplama gerektirdiğini ölçer. Basit bir ",["ETH","ethereum"]," transferi 21.000 gas tüketir; token takası veya ",["NFT","nft"]," basımı gibi karmaşık işlemler çok daha fazlasını gerektirir. Gas fiyatı ise gwei cinsinden ifade edilir; 1 gwei 0,000000001 ETH'dir."],"Ethereum'da her blok için bir temel ücret (base fee) belirlenir ve bu kısım yakılır. Siz ayrıca işleminizin öne alınması için bahşiş (priority fee) ekleyebilirsiniz. Ağ yoğunlaştıkça temel ücret yükselir, sakin saatlerde düşer.",["Borsadan çekim yaparken ödediğiniz ",["çekim ücreti","withdrawal-fee"]," ile gas ücreti aynı şey değildir; borsa çekim ücretini kendi belirler ve zaman zaman ağ maliyetine göre günceller. Layer 2 ağları ve bazı farklı L1'ler, aynı işlemi çok daha düşük gas ücretiyle yapmanıza imkân tanır."]],"example":["Bir ETH transferi 21.000 gas tüketir. Temel ücret 15 gwei, bahşiş 1 gwei ise toplam gas fiyatı 16 gwei'dir. Ücret 21.000 x 16 = 336.000 gwei, yani 0,000336 ETH eder; ETH 3.200 ",["USDT","usdt"]," iken bu yaklaşık 1,08 USDT'dir. Aynı anda 200.000 gas tüketen bir ",["DeFi","defi"]," işlemi yaparsanız ücret 200.000 x 16 = 3.200.000 gwei, yani 0,0032 ETH, yaklaşık 10,24 USDT olur. Ağ yoğunluğunda temel ücret 60 gwei'ye çıkarsa bu tutar yaklaşık dört katına çıkar."],"mistakes":["Cüzdanda gas ödeyecek kadar yerel coin bırakmayıp işlemi gönderememek.","Gas limitini çok düşük ayarlayıp işlemin başarısız olmasına ve yine de ücret ödenmesine yol açmak.","Yoğun saatlerde aceleyle işlem yapıp normalin birkaç katı ücret ödemek."],"faq":[{"q":"Gas ücreti neden bu kadar değişken?","a":"Blok alanı sınırlıdır ve talep arttıkça temel ücret otomatik olarak yükselir. Popüler bir token lansmanı veya sert piyasa hareketleri ücretleri kısa sürede katlayabilir."},{"q":"Başarısız işlemde gas iade edilir mi?","a":"Hayır. İşlem başarısız olsa da o ana kadar harcanan hesaplama için gas ödenir. Kullanılmayan gas limiti ise harcanmaz."},{"q":"Gas ücreti nasıl düşürülür?","a":"Ağın sakin olduğu saatleri seçebilir, bir layer 2 ağı kullanabilir veya cüzdanınızın önerdiği daha düşük ücret seçeneğini, işlemin gecikebileceğini bilerek tercih edebilirsiniz."}],"title":"Gas ücreti nedir? Nasıl hesaplanır?","description":"Gas ücretinin ne olduğunu, gwei ile nasıl hesaplandığını ve Ethereum'da işlem maliyetini nasıl düşürebileceğinizi öğrenin.","related":[["layer-2","Katman 2 (Layer 2, L2)","Katman 2 (Layer 2, L2), işlemleri ana blockchain'in dışında daha hızlı ve ucuz şekilde işleyip sonuçlarını bir Layer 1'e (çoğu zaman Ethereum'a) kaydeden ölçekleme ağıdır."],["mempool","Mempool (bekleyen işlem havuzu)","Mempool, gönderilmiş ama henüz bir bloğa eklenmemiş işlemlerin, madenciler veya doğrulayıcılar tarafından seçilmeyi beklediği bekleme alanıdır."],["withdrawal-fee","Çekim ücreti","Çekim ücreti, bir kripto varlığı borsadan harici bir cüzdana veya başka bir platforma gönderirken borsanın kestiği, genellikle seçilen ağa göre sabit miktarda alınan ücrettir."],["ethereum","Ethereum (ETH)","Ethereum, akıllı kontratların çalıştırılabildiği programlanabilir bir blockchain'dir; yerel coini Ether (ETH) hem işlem ücretlerini (gas) ödemek hem de ağı hisse ispatıyla güvence altına almak için kullanılır."],["smart-contract","Akıllı kontrat (smart contract)","Akıllı kontrat (smart contract), bir blockchain üzerinde çalışan ve önceden yazılmış koşullar gerçekleştiğinde kimsenin onayına gerek kalmadan otomatik olarak işlem yapan bir programdır."]],"lesson":{"id":"E09","slug":"pre-transfer-checklist","ep":9,"title":"Transferden önce: Bunların hiçbirini tahminle yapma"},"coin":{"slug":"ethereum","name":"Ethereum","symbol":"ETH"},"tool":null,"cta":false},"bull-market":{"slug":"bull-market","cat":"basics","en":"Bull market","contentLocale":"tr","term":"Boğa piyasası (bull market)","aka":["boğa sezonu","bull market","boğa"],"short":"Boğa piyasası (bull market), fiyatların uzun bir dönem boyunca genel olarak yükseldiği, yatırımcı iyimserliğinin ve işlem hacminin arttığı piyasa evresidir.","body":["Boğa adı, hayvanın boynuzlarını aşağıdan yukarı savurmasından gelir. Kesin bir tanımı olmasa da kripto piyasasında genellikle dip seviyeden belirgin ve kalıcı bir yükseliş, daha yüksek tepeler ve daha yüksek dipler gördüğünüzde boğa piyasasından söz edilir.","Boğa dönemlerinde yeni yatırımcılar piyasaya girer, borsalardaki hacim artar, yeni token listelemeleri çoğalır ve kaldıraçlı pozisyonlar büyür. Fonlama oranlarının sürekli pozitif olması da long tarafın kalabalık olduğuna işaret edebilir.",["Yükselen bir piyasada bile yüzde 20-30'luk sert düzeltmeler olağandır. ",["Kaldıraç","leverage"]," kullananlar bu ani düşüşlerde likide olabilir. Boğa piyasasının ne zaman başlayıp ne zaman biteceği ancak geriye dönüp bakıldığında netleşir."]],"example":["Bir coinin 20.000 ",["USDT","usdt"],"'den 45.000 USDT'ye çıktığı bir boğa döneminde, fiyat birkaç hafta içinde 45.000'den 36.000'e geri çekilebilir. Bu yüzde 20'lik bir düzeltmedir ama genel eğilim hâlâ yukarı yönlüdür. 10x kaldıraçlı bir long pozisyonu 45.000'den açan biri için ise yaklaşık yüzde 10'luk düşüş, yani 40.500 civarı, teminatın tamamını kaybetmek anlamına gelebilir. Spot alıcı aynı geri çekilmede kâğıt üzerinde yüzde 20 kayıp görür ama pozisyonu kapanmaz."],"mistakes":["Boğa piyasasında fiyatların kesintisiz yükseleceğini varsayıp yüksek kaldıraç kullanmak.","Herkes kazanıyor diye plansız ve zarar durdur emri olmadan alım yapmak.","Yükselişi kendi stratejinizin başarısı sanıp risk büyüklüğünü kontrolsüzce artırmak."],"faq":[{"q":"Boğa piyasası ne kadar sürer?","a":"Belirli bir süresi yoktur; aylarca da yıllarca da sürebilir. Başlangıç ve bitiş genellikle ancak sonradan net olarak görülür."},{"q":"Boğa ve ayı piyasası farkı nedir?","a":"Boğa piyasasında fiyatlar uzun süre yükselir ve iyimserlik hakimdir. Ayı piyasasında ise fiyatlar uzun süre düşer ve karamsarlık öne çıkar."}],"title":"Boğa piyasası (bull market) nedir?","description":"Kriptoda boğa piyasasının ne demek olduğunu, nasıl tanındığını ve yükselişteki sert düzeltmelerin kaldıraç riskini öğrenin.","related":[["bear-market","Ayı piyasası (bear market)","Ayı piyasası (bear market), fiyatların uzun bir dönem boyunca genel olarak düştüğü, yatırımcı karamsarlığının ve düşük ilginin hakim olduğu piyasa evresidir."],["fomo","FOMO (fırsatı kaçırma korkusu)","FOMO (fear of missing out), hızla yükselen bir coini kaçırma korkusuyla plansız, aceleci ve çoğu zaman yükselişin geç bir aşamasında alım yapma eğilimidir."],["all-time-high","Tüm zamanların en yüksek seviyesi (ATH)","Tüm zamanların en yüksek seviyesi (all-time high, ATH), bir kripto paranın işlem görmeye başladığından bu yana ulaştığı en yüksek fiyattır."],["fear-and-greed-index","Korku ve Açgözlülük Endeksi (Fear and Greed Index)","Korku ve Açgözlülük Endeksi, kripto piyasasındaki genel duyguyu 0 ile 100 arasında tek bir sayıyla gösteren; 0 aşırı korkuyu, 100 aşırı açgözlülüğü ifade eden bir göstergedir."]],"lesson":null,"coin":null,"tool":"/onchain","cta":false},"take-profit":{"slug":"take-profit","cat":"trading","en":"Take-profit order","contentLocale":"tr","term":"Kâr al (take-profit) emri","aka":["take-profit","take profit","TP","kâr alma emri"],"short":"Kâr al (take-profit) emri, fiyat önceden belirlediğiniz hedef seviyeye ulaştığında pozisyonunuzu otomatik olarak kapatarak kârı gerçekleştiren emirdir.","body":["Kâr al emri, ekran başında olmadığınızda da hedefinize gelindiğinde pozisyonu kapatır. Spot piyasada çoğu zaman basit bir limit satış emriyle aynı işi görür. Vadeli işlemlerde ise pozisyona bağlı TP/SL alanları olarak, zarar durdur emriyle birlikte ayarlanabilir.",["Kâr hedefi, risk-ödül oranının bir parçasıdır. Örneğin zarar durdurunuz 2 birim uzaktaysa ve kâr hedefiniz 4 birim uzaktaysa ",["risk-ödül oranı","risk-reward-ratio"]," 1:2'dir. Böyle bir oranla, işlemlerin yarısından azında haklı çıksanız bile toplamda kâr edebilirsiniz."],"Bazı yatırımcılar pozisyonun tamamını tek seviyede kapatmak yerine birkaç kademeli kâr al emri kullanır. Kâr al emrinin türü (limit veya market) ve tetik fiyatı seçenekleri borsadan borsaya değişir; bunları emir ekranında kontrol etmek gerekir."],"example":["Bir coini 20 ",["USDT","usdt"],"'den 50 adet aldınız, yani 1.000 USDT'lik pozisyon. Zarar durdurunuz 19 USDT'de (risk 50 USDT), kâr hedefiniz 22 USDT'de. Pozisyonun yarısını 21 USDT'de, kalan yarısını 22 USDT'de satacak iki kademeli kâr al emri koyuyorsunuz. Her iki seviye de dolarsa kârınız 25 x 1 + 25 x 2 = 75 USDT olur. Fiyat yalnızca 21'e gelip geri dönerse 25 USDT kâr cebinize girer ve kalan yarı için zarar durdurunuzu giriş fiyatına çekebilirsiniz."],"mistakes":["Kâr hedefini risk-ödül hesabı yapmadan rastgele seçmek.","Fiyat hedefe yaklaşınca açgözlülükle kâr al emrini sürekli yukarı taşımak.","Vadeli işlemlerde kâr al emrinin pozisyon büyüklüğüyle uyumlu olup olmadığını kontrol etmemek."],"faq":[{"q":"Take-profit ve limit satış emri aynı şey mi?","a":"Spot piyasada sonuç çoğu zaman benzerdir. Vadeli işlemlerde ise take-profit genellikle tetik fiyatıyla çalışan ve pozisyona bağlı ayrı bir emir türüdür."},{"q":"Take-profit ile stop-loss aynı anda kullanılabilir mi?","a":"Evet. Birçok borsa pozisyona bağlı TP/SL ayarı veya OCO emri sunar; biri gerçekleştiğinde diğeri iptal edilir."}],"title":"Take-profit (kâr al) emri nedir?","description":"Kâr al emrinin nasıl çalıştığını, risk-ödül oranıyla ilişkisini ve kademeli kâr almanın nasıl yapıldığını örnekle öğrenin.","related":[["stop-loss","Zarar durdur (stop-loss) emri","Zarar durdur (stop-loss) emri, fiyat önceden belirlediğiniz bir tetik seviyesine ulaştığında pozisyonunuzu otomatik olarak kapatarak kaybınızı sınırlamayı amaçlayan bir emirdir."],["oco-order","OCO emri (biri diğerini iptal eder)","OCO emri (one-cancels-the-other), birbirine bağlı iki emirden oluşan ve biri gerçekleştiği anda diğerinin otomatik olarak iptal edildiği bir emir türüdür; genellikle kâr al ve zarar durdur emrini birlikte koymak için kullanılır."],["risk-reward-ratio","Risk-ödül oranı (Risk-reward ratio)","Risk-ödül oranı, bir işlemde zarar durdur seviyesine kadar göze aldığınız olası kaybı, kâr al hedefindeki olası kazançla karşılaştıran orandır."],["limit-order","Limit emir (limit order)","Limit emir (limit order), yalnızca belirlediğiniz fiyattan veya daha iyisinden gerçekleşen, piyasa o fiyata gelene kadar emir defterinde bekleyen alım ya da satım emridir."]],"lesson":{"id":"E17","slug":"stop-loss-is-a-plan","ep":17,"title":"Kâr al ve zarar durdur plandır, sigorta değil"},"coin":null,"tool":null,"cta":false},"margin-trading":{"slug":"margin-trading","cat":"derivatives","en":"Margin trading","contentLocale":"tr","term":"Marjin ticareti (Margin trading)","aka":["marjinli işlem","teminatlı işlem","margin trading"],"short":"Marjin ticareti, hesabınızdaki varlıkları teminat göstererek borsadan borç alıp sahip olduğunuzdan daha büyük pozisyon açtığınız işlem türüdür.","body":[["Spot marjin ticaretinde borsa size ",["USDT","usdt"]," veya coin ödünç verir. Long için USDT borç alıp coin alırsınız; short için coin borç alıp satarsınız ve daha ucuza geri almayı hedeflersiniz. Borç aldığınız tutar için saatlik veya günlük faiz ödersiniz."],[["Vadeli işlemler","futures-contract"]," de teminat (marjin) mantığıyla çalışır, ancak orada borç alma yoktur ve maliyet faiz yerine ",["fonlama oranı","funding-rate"]," şeklinde ortaya çıkar. Her iki durumda da ",["başlangıç teminatı","initial-margin"]," ve ",["bakım teminatı","maintenance-margin"]," kavramları geçerlidir: teminat oranınız belirli bir seviyenin altına düşerse pozisyonunuz tasfiye edilir."],["Borsalar marjin hesaplarında genellikle izole ve ",["çapraz marjin","cross-margin"]," modları sunar. İzole modda risk tek bir pozisyona sınırlıdır, çapraz modda hesaptaki tüm bakiye ortak teminattır. Faiz oranları, borçlanılabilecek coinler ve maksimum kaldıraç borsaya göre değişir."]],"example":"Marjin hesabınıza 2.000 USDT yatırıp 3x kaldıraçla 4.000 USDT borç alıyorsunuz ve toplam 6.000 USDT ile ETH alıyorsunuz. Borç faizi günlük yüzde 0,02 ise günde 0,8 USDT faiz ödersiniz. ETH yüzde 10 yükselirse varlığınız 6.600 USDT olur; 4.000 USDT borcu düşünce özsermayeniz 2.600 USDT, yani yüzde 30 kâr. ETH yüzde 10 düşerse özsermayeniz 1.400 USDT'ye iner ve yüzde 30 kaybedersiniz.","mistakes":["Borç faizini hesaba katmadan pozisyonu haftalarca açık tutmak.","Marjin ticaretini spot alımla aynı risk seviyesinde görmek; düşüşte tasfiye riski vardır.","Çapraz marjin modunda tüm hesap bakiyesinin teminat olduğunu unutmak."],"faq":[{"q":"Marjin ticareti ile vadeli işlem aynı şey mi?","a":"İkisi de teminat ve kaldıraç kullanır ama farklıdır. Spot marjinde gerçekten borç alıp coin alırsınız ve faiz ödersiniz; vadeli işlemde ise bir sözleşme tutarsınız ve maliyet fonlama şeklindedir."},{"q":"Marjin hesabında ne zaman tasfiye olurum?","a":"Varlıklarınızın borcunuza oranı borsanın belirlediği bakım seviyesinin altına düştüğünde. Kesin eşikler borsaya ve pariteye göre değişir."}],"title":"Marjin ticareti nedir? Kriptoda teminatlı işlem","description":"Kripto marjin ticaretinin nasıl çalıştığını, borç faizini, kaldıracı ve tasfiye riskini örnekle öğrenin.","related":[["leverage","Kaldıraç (Leverage)","Kaldıraç, yatırdığınız teminatın birkaç katı büyüklüğünde pozisyon açmanızı sağlayan ve hem kazancı hem kaybı aynı oranda büyüten bir işlem aracıdır."],["initial-margin","Başlangıç teminatı (Initial margin)","Başlangıç teminatı, kaldıraçlı bir pozisyonu açabilmek için hesabınızda bulunması ve pozisyona bağlanması gereken asgari teminat tutarıdır."],["maintenance-margin","Bakım teminatı (Maintenance margin)","Bakım teminatı, kaldıraçlı bir pozisyonun açık kalabilmesi için hesapta bulunması gereken asgari teminat seviyesidir; teminat bu seviyenin altına inerse likidasyon başlar."],["liquidation","Likidasyon (Tasfiye)","Likidasyon (tasfiye), kaldıraçlı bir pozisyonun teminatı bakım seviyesinin altına düştüğünde borsanın pozisyonu zorla kapatmasıdır."],["cross-margin","Çapraz marjin (Cross margin)","Çapraz marjin, hesaptaki kullanılabilir bakiyenin tamamının tüm açık pozisyonlar için ortak teminat olarak kullanıldığı marjin modudur."]],"lesson":{"id":"E19","slug":"what-leverage-does","ep":19,"title":"10x kaldıraç: Daha fazla para mı, daha fazla risk mi?"},"coin":null,"tool":null,"cta":false},"non-custodial-wallet":{"slug":"non-custodial-wallet","cat":"wallets-security","en":"Non-custodial (self-custody) wallet","contentLocale":"tr","term":"Saklama dışı cüzdan (non-custodial wallet)","aka":["kendi kendine saklama cüzdanı","self-custody cüzdan","non-custodial wallet","emanetsiz cüzdan"],"short":"Saklama dışı cüzdan, özel anahtarları yalnızca sizin kontrol ettiğiniz, bu yüzden fonlarınızı sizden başka kimsenin taşıyamadığı, donduramadığı veya sizin yerinize kurtaramadığı bir kripto cüzdanıdır.","body":[["Kriptonuzu bir borsada tuttuğunuzda anahtarları borsa saklar; sizin elinizde yalnızca borsanın sistemindeki bir bakiye vardır. MetaMask, Trust Wallet, Phantom gibi yazılım cüzdanlarında veya donanım cüzdanlarında ise anahtarlar sizin cihazınızda üretilir ve sadece sizin bildiğiniz bir kurtarma ifadesiyle (",["seed phrase","seed-phrase"],") yedeklenir."],["Bunun avantajı tam kontroldür: borsanın mali durumuna, çekim limitlerine ya da hesap dondurmalarına bağlı kalmazsınız. Ayrıca ",["DeFi","defi"]," uygulamalarına, merkeziyetsiz borsalara (",["DEX","dex"],") ve ",["NFT","nft"]," pazarlarına doğrudan bağlanabilirsiniz."],"Bedeli ise sorumluluktur. Burada \"şifremi unuttum\" butonu yoktur. Kurtarma ifadesini ve cihazı birlikte kaybederseniz fonlara bir daha ulaşamazsınız; ifadeyi başkası ele geçirirse cüzdanı kimseye sormadan boşaltabilir. Bu yüzden birçok kullanıcı işlem için borsayı, uzun vadeli saklama için kendi cüzdanını kullanır."],"example":["Bir borsadan 2 SOL aldığınızı ve bunu saklama dışı cüzdanınıza çektiğinizi varsayalım. Borsa örneğin 0,01 SOL ",["çekim ücreti","withdrawal-fee"]," keserse cüzdanınıza 1,99 SOL ulaşır. Bu andan itibaren borsa bu bakiyeyi donduramaz. Bir yıl sonra telefonunuz bozulursa uygulamayı yeni cihaza kurar, 12 kelimelik kurtarma ifadenizi girer ve aynı 1,99 SOL'u yeniden görürsünüz; çünkü fonlar telefonda değil, blokzincirde durur."],"mistakes":["Kurtarma ifadesini ekran görüntüsü olarak telefonda veya bulut depolamada saklamak.","Kurtarma ifadesi kaybolursa cüzdan uygulamasının destek ekibinin fonları geri getirebileceğini sanmak.","Tanımadığınız sitelerde ne onayladığınızı okumadan işlem imzalamak."],"faq":[{"q":"Saklamalı ve saklama dışı cüzdan arasındaki fark nedir?","a":"Saklamalı cüzdanda anahtarları borsa gibi bir üçüncü taraf tutar. Saklama dışı cüzdanda anahtarlar sizdedir ve işlemleri yalnızca siz imzalayabilirsiniz."},{"q":"Saklama dışı cüzdan tamamen güvenli midir?","a":"Borsa riskini ortadan kaldırır ama riski size taşır. Güvenlik, kurtarma ifadesini ne kadar iyi koruduğunuza ve hangi işlemleri imzaladığınıza bağlıdır."}],"title":"Saklama dışı cüzdan nedir? Non-custodial wallet anlamı","description":"Saklama dışı (non-custodial) cüzdanın nasıl çalıştığını, avantajlarını ve kurtarma ifadesi sorumluluğunu öğrenin.","related":[["custodial-wallet","Emanetçi cüzdan (Custodial wallet)","Emanetçi cüzdan (custodial wallet), kripto varlıklarınızın özel anahtarlarını sizin yerinize bir borsanın veya saklama kuruluşunun tuttuğu cüzdan türüdür."],["seed-phrase","Kurtarma ifadesi (seed phrase)","Kurtarma ifadesi (seed phrase), bir kripto cüzdanının tüm özel anahtarlarının türetildiği 12 veya 24 kelimelik listedir ve bu kelimeleri bilen herkes cüzdanın tamamını kontrol edebilir."],["private-key","Özel anahtar (private key)","Özel anahtar, bir kripto adresindeki varlıkları harcamak için gereken dijital imzayı üreten gizli bir sayıdır ve onu bilen kişi o adresin fiilî sahibi olur."],["hardware-wallet","Donanım cüzdanı (hardware wallet)","Donanım cüzdanı, özel anahtarları güvenli bir çip içinde çevrim dışı saklayan ve işlemleri cihazın kendi ekranında onaylatarak imzalayan küçük bir fiziksel cihazdır."]],"lesson":{"id":"E03","slug":"exchange-vs-wallet","ep":3,"title":"Coin'lerim nerede? Borsa ve cüzdan farkı"},"coin":null,"tool":null,"cta":false},"multisig-wallet":{"slug":"multisig-wallet","cat":"wallets-security","en":"Multisig wallet","contentLocale":"tr","term":"Çoklu imza cüzdanı (multisig)","aka":["multisig","multi-sig cüzdan","çoklu imzalı cüzdan"],"short":"Çoklu imza (multisig) cüzdanı, bir işlemin gerçekleşmesi için birden fazla özel anahtarın onayını gerektiren, örneğin 3 anahtardan 2'sinin imzasını isteyen kripto cüzdanıdır.","body":["Normal bir cüzdanda tek anahtar tüm yetkiye sahiptir; o anahtar kaybolursa veya çalınırsa her şey gider. Multisig'de kural \"M / N\" şeklinde tanımlanır: N anahtar vardır ve işlem için en az M tanesinin imzası gerekir. 2/3 ve 3/5 yaygın düzenlerdir.",["Bu yapı iki sorunu birden çözer. Tek bir anahtar çalınırsa saldırgan tek başına işlem yapamaz. Tek bir anahtar kaybolursa diğer anahtarlarla fonlara hâlâ ulaşabilirsiniz. Bu yüzden şirketler, ",["DAO","dao"]," hazineleri ve büyük birikimi olan bireyler multisig kullanır. ",["Ethereum","ethereum"],"'da Safe, ",["Bitcoin","bitcoin"],"'de birçok cüzdan bu özelliği sunar."],"Dezavantajları kurulum karmaşıklığı ve daha yüksek işlem maliyetidir. Ayrıca anahtarların farklı cihazlarda ve farklı yerlerde saklanması gerekir; hepsi aynı çekmecede duruyorsa multisig'in avantajı kaybolur."],"example":["Üç ortaklı küçük bir şirket hazinesinde 40.000 ",["USDC","usdc"]," tutuyor ve 2/3 multisig kullanıyor. Her ortağın kendi donanım cüzdanında bir anahtarı var. Bir ortağın bilgisayarı ele geçirilse bile saldırgan tek anahtarla 40.000 USDC'yi çekemez. Ortaklardan biri 12.000 USDC tedarikçi ödemesi önerir, ikinci ortak cihazında tutarı ve adresi kontrol edip imzalar ve ödeme gerçekleşir."],"mistakes":["Tüm anahtarları aynı kişide veya aynı yerde saklamak.","Anahtarların yedeklerini ve kurtarma planını belgelememek.","İkinci imzacının işlemi detayları kontrol etmeden otomatik onaylaması."],"faq":[{"q":"Multisig bireysel kullanıcılar için gerekli mi?","a":"Küçük tutarlar için genellikle gereksiz karmaşıklıktır. Büyük birikimlerde tek nokta hatasını azaltmak için değerlendirilebilir."},{"q":"Multisig'de bir anahtarı kaybedersem ne olur?","a":"Kalan anahtar sayısı eşiği karşılıyorsa fonları yeni bir multisig'e taşıyabilirsiniz. Eşiğin altına düşerseniz fonlar kilitli kalabilir."}],"title":"Multisig (çoklu imza) cüzdan nedir? Nasıl çalışır?","description":"Çoklu imza cüzdanının M/N kuralını, tek anahtar riskini nasıl azalttığını ve kurulumda nelere dikkat edileceğini öğrenin.","related":[["private-key","Özel anahtar (private key)","Özel anahtar, bir kripto adresindeki varlıkları harcamak için gereken dijital imzayı üreten gizli bir sayıdır ve onu bilen kişi o adresin fiilî sahibi olur."],["cold-wallet","Soğuk cüzdan (cold wallet)","Soğuk cüzdan, özel anahtarları internete hiç bağlanmayan bir cihazda veya ortamda saklayarak uzaktan çalınma riskini büyük ölçüde azaltan kripto saklama yöntemidir."],["dao","DAO (merkeziyetsiz otonom organizasyon)","DAO, kurallarının akıllı sözleşmelerle tanımlandığı ve kararlarının genellikle yönetişim token'ı sahiplerinin oylarıyla alındığı, yöneticisi tek bir şirket olmayan internet tabanlı bir organizasyondur."],["non-custodial-wallet","Saklama dışı cüzdan (non-custodial wallet)","Saklama dışı cüzdan, özel anahtarları yalnızca sizin kontrol ettiğiniz, bu yüzden fonlarınızı sizden başka kimsenin taşıyamadığı, donduramadığı veya sizin yerinize kurtaramadığı bir kripto cüzdanıdır."]],"lesson":{"id":"E03","slug":"exchange-vs-wallet","ep":3,"title":"Coin'lerim nerede? Borsa ve cüzdan farkı"},"coin":null,"tool":null,"cta":false},"dao":{"slug":"dao","cat":"defi","en":"DAO (decentralized autonomous organization)","contentLocale":"tr","term":"DAO (merkeziyetsiz otonom organizasyon)","aka":["DAO","merkeziyetsiz otonom organizasyon","decentralized autonomous organization"],"short":"DAO, kurallarının akıllı sözleşmelerle tanımlandığı ve kararlarının genellikle yönetişim token'ı sahiplerinin oylarıyla alındığı, yöneticisi tek bir şirket olmayan internet tabanlı bir organizasyondur.","body":[["Bir DAO'da protokol parametreleri, hazine harcamaları veya yeni özellikler için öneriler (proposal) sunulur. Token sahipleri oy kullanır ve yeterli katılım ile çoğunluk sağlanırsa karar uygulanır. Bazı DAO'larda karar doğrudan zincir üstünde otomatik çalışır, bazılarında ise oylama zincir dışında yapılıp bir ",["multisig","multisig-wallet"]," tarafından uygulanır."],["Uniswap, Aave ve MakerDAO (Sky) gibi büyük ",["DeFi","defi"]," protokolleri DAO yapısıyla yönetilir. DAO hazineleri milyonlarca dolarlık varlık tutabilir ve geliştirici ödemeleri, teşvik programları gibi harcamalar oylamayla belirlenir."],"Pratikte DAO'lar kusursuz demokrasi değildir. Oy gücü token miktarına bağlı olduğu için büyük sahipler (balinalar, fonlar, ekip) sonuçları belirleyebilir. Katılım oranları çoğu zaman düşüktür. Hukuki statü de ülkeden ülkeye farklıdır ve bazı yerlerde belirsizdir."],"example":["Bir DAO'nun 10 milyon ",["yönetişim token'ı","governance-token"]," olduğunu ve öneri için en az yüzde 4 katılım, yani 400.000 oy gerektiğini varsayalım. Hazineden bir güvenlik denetimine 200.000 ",["USDC","usdc"]," ayrılması öneriliyor. Oylamaya 600.000 token katılıyor: 450.000 evet, 150.000 hayır. Katılım eşiği aşıldığı ve çoğunluk yüzde 75 evet olduğu için öneri kabul edilir. Sizin 1.000 token'ınız bu oylamada yaklaşık yüzde 0,17'lik bir ağırlık taşır."],"mistakes":["DAO'nun tamamen merkeziyetsiz olduğunu, ekibin hiçbir kontrolü olmadığını varsaymak.","Yönetişim token'ı almanın protokol gelirlerinden otomatik pay vereceğini sanmak.","Önerileri okumadan oy vermek veya oy hakkını kimin kullandığını takip etmemek."],"faq":[{"q":"DAO'ya nasıl katılırım?","a":"Genellikle o DAO'nun yönetişim token'ını edinip oylama platformuna cüzdanınızla bağlanırsınız. Bazı DAO'lar oy hakkını başkasına devretmenize (delegasyon) de izin verir."},{"q":"DAO ile şirket arasındaki fark nedir?","a":"Şirkette kararları yöneticiler ve yönetim kurulu alır. DAO'da kurallar kodda tanımlıdır ve kararlar token sahiplerinin oylarıyla alınır."}],"title":"DAO nedir? Merkeziyetsiz otonom organizasyon anlamı","description":"DAO'ların nasıl çalıştığını, yönetişim oylamalarını, hazine yönetimini ve pratikteki sınırlarını öğrenin.","related":[["governance-token","Yönetişim token'ı (governance token)","Yönetişim token'ı, sahiplerine bir protokolün veya DAO'nun kararlarında oy kullanma hakkı veren kripto token'ıdır; örneğin UNI, Uniswap yönetişiminde kullanılır."],["multisig-wallet","Çoklu imza cüzdanı (multisig)","Çoklu imza (multisig) cüzdanı, bir işlemin gerçekleşmesi için birden fazla özel anahtarın onayını gerektiren, örneğin 3 anahtardan 2'sinin imzasını isteyen kripto cüzdanıdır."],["smart-contract","Akıllı kontrat (smart contract)","Akıllı kontrat (smart contract), bir blockchain üzerinde çalışan ve önceden yazılmış koşullar gerçekleştiğinde kimsenin onayına gerek kalmadan otomatik olarak işlem yapan bir programdır."],["defi","DeFi (merkeziyetsiz finans)","DeFi (merkeziyetsiz finans), borç verme, takas, getiri elde etme gibi finansal hizmetlerin banka veya borsa yerine blokzincirdeki akıllı sözleşmelerle sunulduğu açık uygulamalar ekosistemidir."]],"lesson":null,"coin":{"slug":"uniswap","name":"Uniswap","symbol":"UNI"},"tool":null,"cta":false},"apr-vs-apy":{"slug":"apr-vs-apy","cat":"defi","en":"APR vs APY","contentLocale":"tr","term":"APR ve APY farkı","aka":["APR","APY","yıllık getiri oranı","bileşik yıllık getiri"],"short":"APR, bileşik etki olmadan hesaplanan basit yıllık getiri oranıdır; APY ise kazancın düzenli olarak yeniden yatırıldığı varsayımıyla bileşik getiriyi gösterir, bu yüzden aynı oran için APY her zaman APR'den yüksek veya ona eşittir.","body":["APR (annual percentage rate), yıllık basit faiz gibidir: yüzde 12 APR, bir yılda anaparanın yüzde 12'si kadar getiri demektir. APY (annual percentage yield) ise getirinin belirli aralıklarla anaparaya eklendiğini ve bir sonraki dönemde onun da getiri ürettiğini varsayar.","Bileşik sıklığı arttıkça fark büyür. Günlük bileşik, aylık bileşikten biraz daha yüksek APY üretir. Platformlar bazen daha yüksek göründüğü için APY'yi öne çıkarır. Ürünleri karşılaştırırken aynı ölçüyü kullanmak ve bileşiğin otomatik mi yoksa sizin yeniden yatırmanızla mı gerçekleştiğini kontrol etmek gerekir.",["Kriptoda gösterilen oranlar genellikle değişkendir; ",["staking","staking"]," ödülleri, borç verme faizleri ve havuz ücretleri piyasa koşuluna göre değişir. Ayrıca getiri farklı bir token'la ödeniyorsa, o token'ın fiyat hareketi gerçek getirinizi değiştirir. ",["Fonlama oranı","funding-rate"]," da yıllıklaştırıldığında benzer biçimde APR olarak ifade edilebilir."]],"example":["1.000 ",["USDT","usdt"],"'yi yüzde 12 APR ile bir yıl yatırdığınızı varsayalım. Bileşik olmazsa yıl sonunda 120 USDT kazanır, 1.120 USDT'ye ulaşırsınız. Getiri aylık olarak eklenirse aylık oran yüzde 1 olur ve 1.000 × 1,01^12 = yaklaşık 1.126,8 USDT elde edersiniz; bu yaklaşık yüzde 12,68 APY'dir. Aradaki 6,8 USDT bileşiğin etkisidir."],"mistakes":["Bir üründe APR, diğerinde APY görüp ikisini doğrudan karşılaştırmak.","Değişken oranı yıl boyunca sabit kalacakmış gibi hesaplamak.","Bileşiğin otomatik olmadığı ürünlerde APY rakamına güvenmek."],"faq":[{"q":"APY her zaman APR'den yüksek mi?","a":"Bileşik etki olduğunda evet. Bileşik yapılmıyorsa ikisi eşittir."},{"q":"Kripto getirilerinde hangisine bakmalıyım?","a":"Karşılaştırdığınız ürünlerin hepsini aynı ölçüye çevirin. Getiri sizin yeniden yatırmanıza bağlıysa APR daha gerçekçi bir referanstır."}],"title":"APR ve APY farkı nedir? Kripto getirisi nasıl hesaplanır?","description":"APR ile APY arasındaki farkı, bileşik getirinin etkisini ve kripto getiri ürünlerini doğru karşılaştırmayı örnekle öğrenin.","related":[["staking","Staking (stake etme)","Staking, hisse kanıtı (proof of stake) kullanan bir blokzincirde coinlerinizi ağın güvenliği ve blok doğrulaması için kilitleyip karşılığında ağ ödülü almanızdır."],["yield-farming","Getiri çiftçiliği (yield farming)","Getiri çiftçiliği (yield farming), kripto varlıkları DeFi protokollerine likidite, borç veya stake olarak yatırıp ücret, faiz ve ödül token'larıyla getiri elde etmeye çalışma stratejisidir."],["crypto-earn","Kripto kazanç ürünleri (Earn)","Kripto kazanç (Earn) ürünleri, borsaların kullanıcıların coin'lerini esnek veya vadeli olarak yatırıp karşılığında faiz benzeri getiri almasını sağlayan birikim ve getiri ürünleridir."],["funding-rate","Fonlama oranı (Funding rate)","Fonlama oranı, sürekli (perpetual) vadeli kontrat fiyatını spot fiyata yakın tutmak için long ve short pozisyon sahipleri arasında düzenli aralıklarla yapılan ödemenin oranıdır."]],"lesson":null,"coin":null,"tool":null,"cta":false},"algorithmic-stablecoin":{"slug":"algorithmic-stablecoin","cat":"stablecoins","en":"Algorithmic stablecoin","contentLocale":"tr","term":"Algoritmik stablecoin","aka":["algoritmik sabit coin","algorithmic stablecoin"],"short":"Algoritmik stablecoin, fiyatını tam rezerv yerine arz-talebi otomatik ayarlayan kurallar ve çoğu zaman ikinci bir token ile 1 dolarda tutmaya çalışan stablecoin türüdür.","body":[["Klasik ",["stablecoin","stablecoin"],"'lerin arkasında nakit, bono ya da kripto teminat bulunur. Algoritmik modelde ise teminat ya hiç yoktur ya da kısmidir. Sistem, fiyat 1 doların üstüne çıkınca yeni coin basar, altına inince coin'i dolaşımdan çeker. Bunu çoğu zaman ikinci bir dalgalı token üzerinden yapar."],"En bilinen örnek Terra'nın UST'sidir. UST, LUNA token'ı ile basılıp yakılabiliyordu. Mayıs 2022'de güven kaybolunca kullanıcılar UST'den toplu çıkış yaptı, sistem LUNA'yı sınırsız basmaya başladı ve iki token da neredeyse sıfırlandı. Buna ölüm sarmalı denir.","Bu deneyimden sonra tamamen algoritmik modeller büyük ölçüde güven kaybetti. Bugün yeni projeler genellikle kısmi teminat veya farklı mekanizmalarla ilerler. Bir stablecoin'in yüksek getiri vaat etmesi, arkasında neyin durduğunu sorgulamanız için iyi bir sinyaldir."],"example":"Bir algoritmik stablecoin'in 0,95 dolara düştüğünü düşünün. Kural şöyle: 1 stablecoin'i protokole verene 1 dolar değerinde yardımcı token verilir. Arbitrajcı 0,95 dolara stablecoin alır, 1 dolarlık yardımcı token alır ve 0,05 dolar kâr eder. Bu alımlar fiyatı yukarı iter. Ama herkes aynı anda çıkmak isterse yardımcı token sürekli basılır, fiyatı 1 dolardan 0,10 dolara iner ve 1 milyon stablecoin'i kurtarmak için 10 milyon yeni token gerekir. Sistem kendini besleyen bir düşüşe girer.","mistakes":["Yüksek faiz veren bir stablecoin'in USDT ya da USDC kadar güvenli olduğunu varsaymak.","Mekanizmanın düşüş senaryosunda nasıl davrandığını okumadan büyük tutar yatırmak.","Kısa süreli bir toparlanmayı sistemin sağlam olduğunun kanıtı saymak."],"faq":[{"q":"UST neden çöktü?","a":"UST'nin sabiti LUNA ile yapılan basma-yakma mekanizmasına dayanıyordu. Toplu çıkış başlayınca LUNA arzı patladı, fiyatı çöktü ve sabit tekrar kurulamadı."},{"q":"Algoritmik stablecoin'ler hâlâ var mı?","a":"Var, ancak çoğu artık kısmen teminatlı veya hibrit tasarımlar kullanıyor. Her projenin teminatını ve stres senaryosunu ayrı ayrı incelemek gerekir."}],"title":"Algoritmik stablecoin nedir? UST çöküşünden dersler","description":"Algoritmik stablecoin nasıl çalışır, ölüm sarmalı nedir ve Terra UST neden çöktü; basit bir sayısal örnekle öğrenin.","related":[["depeg","Depeg (sabitin kopması)","Depeg, bir stablecoin'in bağlı olduğu değerden, örneğin 1 dolardan, belirgin ve kalıcı biçimde uzaklaşmasıdır; coin artık hedef fiyatında işlem görmez."],["stablecoin","Stablecoin (sabit coin)","Stablecoin, değerini genellikle ABD doları gibi bir referans varlığa sabitlemeyi amaçlayan ve kripto piyasasında nakit gibi kullanılan bir kripto paradır."],["crypto-backed-stablecoin","Kripto teminatlı stablecoin","Kripto teminatlı stablecoin, dolar rezervi yerine akıllı sözleşmede kilitlenen ETH gibi kripto varlıklarla, genellikle değerinden fazla teminatla desteklenen stablecoin'dir."],["synthetic-dollar","Sentetik dolar (delta nötr stablecoin)","Sentetik dolar, spot kripto varlığı tutup aynı büyüklükte short vadeli pozisyon açarak fiyat riskini sıfırlayan ve böylece yaklaşık 1 dolar değerinde kalmayı hedefleyen token'dır."]],"lesson":{"id":"E02","slug":"is-usdt-a-dollar","ep":2,"title":"USDT dolar mı? Kripto alırken neden her yerde karşımıza çıkar?"},"coin":null,"tool":null,"cta":false}});
